<?php

namespace Bga\Games\RegroupChickenArmy\States;

use Bga\Games\RegroupChickenArmy\Components\Market;
use Bga\Games\RegroupChickenArmy\Game;
use BgaUserException;
use BgaVisibleSystemException;

class TurnSetupStateHandler implements StateHandlerInterface
{
    /* AUTOGENERATED_HANDLE_START - DO NOT REMOVE THIS COMMENT */
    public static function handle(Game $game, string $action, ...$args): void
    {
        switch ($action) {

            default:
                throw new BgaVisibleSystemException("Invalid action: $action");
        }
    }
    /* AUTOGENERATED_HANDLE_END - DO NOT REMOVE THIS COMMENT */


    public static function executeGameState(Game $game): void
    {
        $hasEnoughCards = Market::hasEnoughCards($game);

        if (!$hasEnoughCards) {
            $game->notifyAllPlayers("notEnoughCards", clienttranslate("There is not enough cards in the market, ending the game"), []);

            $game->gamestate->nextState('gameOver');
            return;
        }

        $marketCards = Market::getAllMarketCards($game);

        $game->notifyAllPlayers("marketUpdate", clienttranslate("The Market has been updated"), [
            "cards" => $marketCards
        ]);

        $game->gamestate->nextState('startRound');
    }
}

